components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 48px;
  min-width: 48px;
  padding: 0 20px;
  border: none;
  border-radius: 999px;
  background: #C62E3A;
  color: #FFF9F5;
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: 0.005em;
  line-height: 1;
  cursor: pointer;
  box-shadow: 0 6px 18px -8px rgba(198, 46, 58, 0.75);
  transition: background-color 160ms ease, transform 120ms ease, box-shadow 160ms ease;
}
.ds-btn-primary:hover { background: #A3202B; box-shadow: 0 8px 22px -9px rgba(163, 32, 43, 0.8); }
.ds-btn-primary:active { transform: translateY(1px); }
.ds-btn-primary:focus-visible { outline: 2px solid #1F5C4A; outline-offset: 3px; }

.ds-btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 48px;
  padding: 0 20px;
  border: none;
  border-radius: 999px;
  background: #1F5C4A;
  color: #FAF7F2;
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.95rem;
  font-weight: 600;
  line-height: 1;
  cursor: pointer;
  transition: background-color 160ms ease, transform 120ms ease;
}
.ds-btn-secondary:hover { background: #113A2E; }
.ds-btn-secondary:active { transform: translateY(1px); }
.ds-btn-secondary:focus-visible { outline: 2px solid #C62E3A; outline-offset: 3px; }

.ds-field-label {
  display: block;
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #1F5C4A;
}
.ds-field {
  display: block;
  width: 100%;
  min-height: 48px;
  margin-top: 6px;
  padding: 12px 16px;
  border: 1px solid transparent;
  border-radius: 14px;
  background: #83C3B0;
  color: #10312A;
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
  font-size: 1rem;
  font-weight: 500;
  transition: background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}
.ds-field::placeholder { color: #5D7770; opacity: 1; }
.ds-field:hover { background: #8FCCB9; }
.ds-field:focus {
  outline: none;
  background: #96D0BE;
  border-color: #1F5C4A;
  box-shadow: 0 0 0 3px rgba(31, 92, 74, 0.16);
}

.ds-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 12px;
  border-radius: 999px;
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
}
.ds-chip-high { background: rgba(198, 46, 58, 0.1); color: #A3202B; }
.ds-chip-med { background: rgba(242, 193, 68, 0.25); color: #6B4E05; }
.ds-chip-low { background: rgba(131, 195, 176, 0.3); color: #1F5C4A; }

.ds-group-card {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-radius: 18px;
  background: #FAF7F2;
  box-shadow: 0 1px 2px rgba(17, 58, 46, 0.04), 0 8px 24px -12px rgba(17, 58, 46, 0.18);
  text-decoration: none;
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
  transition: transform 160ms ease, box-shadow 160ms ease;
}
.ds-group-card:hover { transform: translateY(-1px); box-shadow: 0 2px 4px rgba(17, 58, 46, 0.06), 0 14px 28px -14px rgba(17, 58, 46, 0.26); }
.ds-group-card:focus-visible { outline: 2px solid #1F5C4A; outline-offset: 3px; }
.ds-group-card-thumb {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 52px;
  height: 52px;
  border-radius: 14px;
  background: #E3EEE9;
}
.ds-group-card-body { display: grid; flex: 1 1 auto; gap: 2px; min-width: 0; }
.ds-group-card-name { font-size: 1.02rem; font-weight: 600; line-height: 1.3; color: #17241F; }
.ds-group-card-meta { font-size: 0.76rem; font-weight: 400; line-height: 1.35; color: #45605A; }
.ds-group-card-chevron { flex: 0 0 auto; opacity: 0.75; }

.ds-pine-header {
  position: relative;
  padding: 28px 24px 24px;
  border-radius: 28px;
  background-image: radial-gradient(120% 90% at 22% 0%, #2D7059 0%, transparent 58%), linear-gradient(160deg, #22624F 0%, #1F5C4A 52%, #1A5142 100%);
  color: #FAF7F2;
  text-align: center;
  box-shadow: 0 10px 30px -12px rgba(17, 58, 46, 0.45);
  overflow: hidden;
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
}
.ds-pine-header::after { content: ""; position: absolute; inset: 0; border-radius: inherit; border: 1px solid rgba(250, 247, 242, 0.1); pointer-events: none; }
.ds-pine-header h2 { margin: 0; font-size: 1.7rem; font-weight: 600; line-height: 1.15; letter-spacing: -0.01em; }
.ds-pine-header p { max-width: 34ch; margin: 6px auto 0; font-size: 0.9rem; font-weight: 400; line-height: 1.4; color: rgba(250, 247, 242, 0.8); }
.ds-pine-header-badge {
  display: inline-block;
  margin-top: 20px;
  padding: 8px 16px;
  border-radius: 999px;
  border: 1px solid rgba(250, 247, 242, 0.15);
  background: rgba(255, 255, 255, 0.06);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.ds-dock {
  width: 100%;
  max-width: 430px;
  margin: 0 auto;
  padding: 12px 20px calc(12px + env(safe-area-inset-bottom, 0px));
  background: linear-gradient(to top, #E3EEE9 62%, rgba(227, 238, 233, 0.92) 82%, transparent);
  font-family: Poppins, ui-sans-serif, system-ui, sans-serif;
}
.ds-dock-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 52px;
  border: none;
  border-radius: 999px;
  background: #C62E3A;
  color: #FFF9F5;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 6px 18px -8px rgba(198, 46, 58, 0.75);
  transition: background-color 160ms ease, transform 120ms ease;
}
.ds-dock-btn:hover { background: #A3202B; }
.ds-dock-btn:active { transform: translateY(1px); }
.ds-dock-btn:focus-visible { outline: 2px solid #1F5C4A; outline-offset: 3px; }
